1	import { Injectable, computed, signal } from '@angular/core';
2	
3	export interface CartItem {
4	  productId: string;
5	  productName: string;
6	  supplierId: string;
7	  supplierName: string;
8	  unitPrice: number;
9	  quantity: number;
10	}
11	
12	@Injectable({ providedIn: 'root' })
13	export class CartService {
14	  private readonly _items = signal<CartItem[]>([]);
15	  readonly items = this._items.asReadonly();
16	  readonly totalAmount = computed(() => this._items().reduce((sum, item) => sum + item.unitPrice * item.quantity, 0));
17	
18	  addItem(item: {
19	    productId: string;
20	    productName: string;
21	    supplierId: string;
22	    supplierName: string;
23	    unitPrice: number;
24	    quantity: number;
